def rotate_cw(grid):
    return [list(row) for row in zip(*grid[::-1])]


def rotate_ccw(grid):
    return [list(row) for row in zip(*grid)][::-1]


def transform(grid):
    cw = rotate_cw(grid)
    ccw = rotate_ccw(grid)
    half = [row + rot for row, rot in zip(grid, cw)]
    lower = [row + rot for row, rot in zip(ccw, [list(row) for row in zip(*grid[::-1])][::-1])]
    return half + lower
